import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt(), boot = 0, app = 0;
        for (int i = 0; i < n; i++) {
            Class<?> type = Class.forName(s.next());
            String module = type.getModule().getName();
            boolean bootstrap = type.getClassLoader() == null;
            if (bootstrap) boot++;
            else app++;
            System.out.println("simple=" + type.getSimpleName() + " module=" + (module == null ? "unnamed" : module) + " loader=" + (bootstrap ? "bootstrap" : "application"));
        }
        System.out.println("bootstrap=" + boot + " application=" + app);
    }
}

