import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int limit = s.nextInt(), n = s.nextInt(), evicted = 0, seq = 0;
        LinkedHashMap<String, Integer> cache = new LinkedHashMap<>(16, 0.75f, true);
        for (int i = 0; i < n; i++) {
            String op = s.next(), key = s.next();
            if (op.equals("put")) {
                cache.put(key, ++ seq);
                if (cache.size() > limit) {
                    Iterator<String> it = cache.keySet().iterator();
                    it.next();
                    it.remove();
                    evicted++;
                }
                System.out.println("put " + key + " size=" + cache.size());
            } else {
                Integer found = cache.get(key);
                System.out.println((found == null ? "miss " : "hit ") + key);
            }
        }
        System.out.println("keys=" + new ArrayList<>(cache.keySet()));
        System.out.println("evicted=" + evicted);
    }
}

